mapper.select:
select page.*, ac.approval_no, ac.approval_status from ( select tr.id, tr.tenant_id, tr.request_id, wd.workflow_code, tr.biz_date, tr.request_status, tr.trace_id, tr.created_at, tr.updated_at from batch.trigger_request tr join batch.workflow_definition wd on wd.tenant_id = tr.tenant_id and wd.id = tr.workflow_definition_id where tr.tenant_id = #{tenantId} and tr.trigger_type = 'CATCH_UP' and tr.request_status = 'ACCEPTED'
and tr.id < #{cursorId}
and wd.workflow_code = #{workflowCode}
and tr.request_id = #{requestId}
and tr.biz_date = cast(#{bizDate} as date)
and (tr.request_id ilike '%' || #{keyword} || '%' or wd.workflow_code ilike '%' || #{keyword} || '%' or tr.trace_id ilike '%' || #{keyword} || '%')
order by tr.id desc
limit #{pageRequest.pageSize}
) page left join lateral ( select approval_no, approval_status from batch.approval_command where tenant_id = page.tenant_id and target_id = page.request_id and approval_type = 'CATCH_UP' order by id desc limit 1 ) ac on true order by page.id desc

select count(1) from batch.trigger_request tr join batch.workflow_definition wd on wd.tenant_id = tr.tenant_id and wd.id = tr.workflow_definition_id where tr.tenant_id = #{tenantId} and tr.trigger_type = 'CATCH_UP' and tr.request_status = 'ACCEPTED'
and wd.workflow_code = #{workflowCode}
and tr.request_id = #{requestId}
and tr.biz_date = cast(#{bizDate} as date)
and (tr.request_id ilike '%' || #{keyword} || '%' or wd.workflow_code ilike '%' || #{keyword} || '%' or tr.trace_id ilike '%' || #{keyword} || '%')
